// Parse da resposta do classificador
const responseText = $input.first().json.content[0].text;

// Tenta extrair JSON da resposta
let classificacao;
try {
  // Remove possivel markdown code block
  const cleanText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  classificacao = JSON.parse(cleanText);
} catch (e) {
  classificacao = {
    categoria: 'OUTRO',
    confianca: 0.5,
    area: 'Nao classificado',
    energia: 'media'
  };
}

// Dados originais
const mensagemOriginal = $('Telegram Trigger').first().json.message.text;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const userName = $('Telegram Trigger').first().json.message.from.first_name || 'Usuario';

return [{
  json: {
    mensagem: mensagemOriginal,
    chatId: chatId,
    userName: userName,
    categoria: classificacao.categoria,
    confianca: classificacao.confianca,
    area: classificacao.area,
    energia: classificacao.energia,
    timestamp: new Date().toISOString()
  }
}];

