// Extrai a resposta do agente (Claude ou Gemini)
const input = $input.first().json;
let respostaAgente = '';

// Tenta formato Claude
if (input.content && input.content[0] && input.content[0].text) {
  respostaAgente = input.content[0].text;
}
// Tenta formato Gemini
else if (input.candidates && input.candidates[0]) {
  respostaAgente = input.candidates[0].content.parts[0].text;
}
else {
  respostaAgente = 'Desculpe, nao consegui processar sua solicitacao. Tente novamente.';
}

// Recupera dados do parse
const parseData = $('Parse Classificacao').first().json;

// Limita resposta pra Telegram (4096 chars)
if (respostaAgente.length > 4000) {
  respostaAgente = respostaAgente.substring(0, 3997) + '...';
}

return [{
  json: {
    chatId: parseData.chatId,
    resposta: respostaAgente,
    categoria: parseData.categoria,
    area: parseData.area,
    energia: parseData.energia,
    mensagemOriginal: parseData.mensagem,
    userName: parseData.userName,
    timestamp: parseData.timestamp
  }
}];
